(() => {
  try {
    const stats = {};
    const moneyMatch = document.body.innerText.match(/\u{1F4B0}\s*([\d,]+)\s*元/);
    const staminaMatch = document.body.innerText.match(/\u{26A1}\s*(\d+)\s*\/\s*(\d+)/);
    const healthMatch = document.body.innerText.match(/\u{2764}\u{FE0F}\s*(\d+)\s*\/\s*(\d+)/);
    const riceMatch = document.body.innerText.match(/水稻：\s*([\d,]+)\s*斤/);
    const sweetPotatoMatch = document.body.innerText.match(/红薯：\s*([\d,]+)\s*斤/);
    const seasonMatch = document.body.innerText.match(/(春季|夏季|秋季|冬季)\s*第\s*(\d+)\s*天/);
    const totalDayMatch = document.body.innerText.match(/\[第(\d+)天\]/g);
    const fieldMatches = document.body.innerText.match(/第\d+块田/g);
    const uniqueFields = [...new Set(fieldMatches || [])];
    const eventCount = (document.body.innerText.match(/\[第\d+天\]/g) || []).length;

    stats.money = moneyMatch ? moneyMatch[1] : null;
    stats.stamina = staminaMatch ? staminaMatch[1] + '/' + staminaMatch[2] : null;
    stats.health = healthMatch ? healthMatch[1] + '/' + healthMatch[2] : null;
    stats.rice = riceMatch ? riceMatch[1] : null;
    stats.sweetPotato = sweetPotatoMatch ? sweetPotatoMatch[1] : null;
    stats.season = seasonMatch ? seasonMatch[1] : null;
    stats.seasonDay = seasonMatch ? seasonMatch[2] : null;
    stats.totalDays = totalDayMatch ? Math.max(...totalDayMatch.map(m => parseInt(m.match(/\d+/)[0]))) : null;
    stats.fields = uniqueFields.length;
    stats.fieldNames = uniqueFields;
    stats.eventCount = eventCount;

    return JSON.stringify(stats);
  } catch(e) {
    return JSON.stringify({error: e.message});
  }
})()
